from decimal import Decimal


def subtotal(items):
    total = Decimal("0")
    for item in items:
        if item.quantity <= 0:
            continue
        total += item.price * item.quantity
    return total


def describe(order):
    return f"Order {order.id}"


def tax(amount, rate):
    return amount * rate


def shipping(weight, express=False):
    if express:
        return Decimal("19.99")
    if weight < 1:
        return Decimal("4.99")
    return Decimal("9.99")
